import { AxisScale } from '@visx/axis';
import React from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { AreaCanvas } from '../../core/components/canvas/components/AreaCanvas.js';
import { LineCanvas } from '../../core/components/canvas/components/LineCanvas.js';
import {
  CanvasGradientGenerator,
  ShapeBuilderPayload,
} from '../../core/components/canvas/functions/create-canvas-gradient.js';
import { SeriesCurve } from '../../core/types/timeseries.js';
import {
  definedAccessor,
  xAxisAccessor,
  y0Accessor,
  y1Accessor,
  yAccessor,
} from '../functions/accessors.js';
import {
  SparklineDatapointMetadata,
  SparklineVariant,
} from '../types/sparkline.js';

interface SparklineDisplayProps {
  data: SparklineDatapointMetadata[];
  width: number;
  height: number;
  xScale: AxisScale<number>;
  yScale: AxisScale<number>;
  strokeColor: string;
  fillColor: string | CanvasGradientGenerator;
  variant: SparklineVariant;
  strokeWidth: number;
  curve?: SeriesCurve;
}

export const SparklineDisplay = ({
  data,
  width,
  height,
  xScale,
  yScale,
  fillColor,
  strokeColor,
  variant,
  strokeWidth,
  curve,
}: SparklineDisplayProps) => {
  const areaColor =
    typeof fillColor === 'string'
      ? () => fillColor
      : () =>
          ({ context }: ShapeBuilderPayload) =>
            fillColor({ context });
  const areaStrokeColor = () => Colors.Background.Base.Default;
  const zeroAxis = (data: SparklineDatapointMetadata) =>
    yAccessor(yScale)({ ...data, value: 0 });

  // TODO canvas animation improvements + enablement tackled in ADES-4720
  const animation = {
    enabled: false,
  };

  return variant === 'area' ? (
    <AreaCanvas
      data={data}
      canvasWidth={width}
      canvasHeight={height}
      x={xAxisAccessor(xScale)}
      y1={y1Accessor(yScale)}
      y0={y0Accessor(yScale)}
      defined={definedAccessor}
      zeroAxis={y0Accessor(yScale)}
      color={areaColor}
      strokeColor={areaStrokeColor}
      strokeWidth={0}
      lineStrokeWidth={strokeWidth}
      lineColor={() => strokeColor}
      animation={animation}
      curve={curve}
    />
  ) : (
    <LineCanvas
      data={data}
      canvasWidth={width}
      canvasHeight={height}
      x={xAxisAccessor(xScale)}
      y={yAccessor(yScale)}
      defined={definedAccessor}
      zeroAxis={zeroAxis}
      color={() => strokeColor}
      strokeWidth={strokeWidth}
      animation={animation}
      curve={curve}
    />
  );
};
